SELECT a.cablestatus, 
    CASE WHEN lower(trim(a.cablestatus)) IN ('available', 'avail', 'yes', 'y') THEN 4 ELSE 1 END as facility_score
FROM amenities a LIMIT 20;

-- Method 1: AVG of (sum of scores / 3) per row
SELECT ROUND(AVG(
    (CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END +
     CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END +
     CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END) / 3.0
), 2) as method1 FROM infrastructure i;

-- Method 2: Average of three separate averages
SELECT ROUND((
    AVG(CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END) +
    AVG(CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END) +
    AVG(CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END)
) / 3.0, 2) as method2 FROM infrastructure i;

SELECT ROUND(AVG(
    (CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END +
     CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END +
     CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END) / 3.0
), 2) as method1 FROM infrastructure i;

-- Average directly from infrastructure (75 rows)
SELECT ROUND(AVG(
    (CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END +
     CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END +
     CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END) / 3.0
), 2) as avg_infra FROM infrastructure i;

SELECT ROUND(AVG(
    (CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END +
     CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END +
     CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END) / 3.0
), 2) as output_value FROM infrastructure i;

-- Try: average of amenity score only
SELECT ROUND(AVG(
    CASE WHEN lower(trim(a.cablestatus)) IN ('available', 'avail', 'yes', 'y') THEN 4 ELSE 1 END
), 2) as output_value FROM amenities a;

-- Check if there's any column with 'priority' or similar
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name ILIKE '%priority%' OR column_name ILIKE '%rating%' OR column_name ILIKE '%score%';

