-- Try different interpretations
-- Maybe it's just counting how many have good facilities
SELECT ROUND(100.0 * AVG(
    CASE WHEN lower(trim(a.cablestatus)) IN ('available', 'avail', 'yes', 'y') THEN 1 ELSE 0 END
), 2) as output_value FROM amenities a;

SELECT ROUND(AVG((p.dwelling_specs->>'Room_Count')::int), 2) as avg_rooms,
       ROUND(AVG((p.dwelling_specs->>'Bath_Count')::int), 2) as avg_baths
FROM properties p;

SELECT ROUND(AVG(
    (CASE WHEN i.wateraccess ILIKE 'yes%' THEN 4 ELSE 1 END +
     CASE WHEN i.roadsurface ILIKE '%asphalt%' OR i.roadsurface ILIKE '%concrete%' THEN 4 ELSE 1 END +
     CASE WHEN lower(trim(i.parkavail)) = 'available' THEN 4 ELSE 1 END) / 3.0
), 2) as avg_rating FROM infrastructure i;

-- Maybe building facilities = amenities, and we need to join with households to get zone info
SELECT ROUND(AVG(
    CASE WHEN lower(trim(a.cablestatus)) IN ('available', 'avail', 'yes', 'y') THEN 4 ELSE 1 END
), 2) as avg_rating
FROM amenities a
JOIN households h ON a.houseid = h.housenum;

